package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.jsoup.helper.Validate;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class XmlDeclaration_getWholeDeclaration_TriageGen1Test {

    private XmlDeclaration xmlDeclaration;

    @Before
    public void setUp() {
        xmlDeclaration = new XmlDeclaration("xml", "http://example.com", false);
    }

    @Test
    public void testGetWholeDeclaration_NoAttributes() {
        assertEquals("xml", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_WithVersion() {
        xmlDeclaration.attributes.put("version", "1.0");
        assertEquals("xml version=\"1.0\"", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_WithEncoding() {
        xmlDeclaration.attributes.put("encoding", "UTF-8");
        assertEquals("xml encoding=\"UTF-8\"", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_WithVersionAndEncoding() {
        xmlDeclaration.attributes.put("version", "1.0");
        xmlDeclaration.attributes.put("encoding", "UTF-8");
        assertEquals("xml version=\"1.0\" encoding=\"UTF-8\"", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_WithOtherName() {
        XmlDeclaration otherDecl = new XmlDeclaration("DOCTYPE", "http://example.com", false);
        assertEquals("DOCTYPE", otherDecl.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_WithNoAttributesButNameNotXml() {
        XmlDeclaration otherDecl = new XmlDeclaration("DOCTYPE", "http://example.com", false);
        otherDecl.attributes.put("version", "1.0");
        otherDecl.attributes.put("encoding", "UTF-8");
        assertEquals("DOCTYPE", otherDecl.getWholeDeclaration());
    }
}
